if (!current_user_can('edit_theme_options')) throw new RuntimeException('header_permission_missing');
global $wpdb;
$builder=\XTS\Modules\Header_Builder::get_instance();
$classes=[];foreach(['builder'=>$builder,'factory'=>$builder->factory,'list'=>$builder->list,'elements'=>$builder->elements] as $k=>$obj){$r=new ReflectionClass($obj);$classes[$k]=['class'=>get_class($obj),'methods'=>get_class_methods($obj),'source'=>file_get_contents($r->getFileName())];}
$dir=get_template_directory().'/inc/modules/header-builder';$entries=scandir($dir);$elementFiles=[];if(is_dir($dir.'/elements'))foreach(scandir($dir.'/elements') as $f){if(preg_match('/logo|main|account|cart|row|text/i',$f)&&is_file($dir.'/elements/'.$f))$elementFiles[$f]=file_get_contents($dir.'/elements/'.$f);}
$id='header_193941';$matches=[];$walk=function($v,$path)use(&$walk,&$matches,$id){if(is_array($v))foreach($v as $k=>$child)$walk($child,$path.'.'.$k);elseif(is_string($v)&&str_contains($v,$id))$matches[]=['path'=>$path,'exact'=>$v===$id,'css'=>str_contains($v,'whb-'.$id)];};$walk(get_option('xts-woodmart-options',[]),'theme');$walk(get_option('xts-options-presets',[]),'presets');
$customPosts=$wpdb->get_results($wpdb->prepare("SELECT ID,post_type FROM {$wpdb->posts} WHERE post_content LIKE %s",'%'.$wpdb->esc_like('whb-'.$id).'%'),ARRAY_A);
$childMatches=[];$child=get_stylesheet_directory();if($child!==get_template_directory()){foreach(new RecursiveIteratorIterator(new RecursiveDirectoryIterator($child,FilesystemIterator::SKIP_DOTS)) as $f){if($f->isLink()||!$f->isFile()||$f->getSize()>2097152||!preg_match('/\.(php|css|js)$/',$f->getFilename()))continue;$s=file_get_contents($f->getPathname());if(str_contains($s,$id)||str_contains($s,'woodmart_get_current_header_id'))$childMatches[]=substr($f->getPathname(),strlen($child));}}
$snippetMatches=[];$table=$wpdb->prefix.'snippets';if($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',$wpdb->esc_like($table)))===$table){foreach($wpdb->get_results("SELECT id,code,active FROM `$table` WHERE active=1",ARRAY_A) as $s){if(str_contains($s['code'],$id)||str_contains($s['code'],'woodmart_get_current_header_id'))$snippetMatches[]=['id'=>$s['id'],'hash'=>hash('sha256',$s['code'])];}}
$logoUrl='https://primevapeoutlet.com/wp-content/uploads/2026/10/header-logo.png';$logoId=attachment_url_to_postid($logoUrl);
